(() => {
  // House reference versions: numerical defaults are not certified original recipes.
  const make=(start,water,temp,valve,nextTime,note='')=>stepDefaults({start,water,temp,valve,until:nextTime||'',next:nextTime?'指定時間':'等流完',note});
  const release=(start)=>stepDefaults({action:'開閥放水',start,valve:'開',next:'等流完',until:''});
  const additions=[
    {id:'kasuya-devil',title:'粕谷哲 · Hybrid / Devil',author:'手法參考改編 · 非官方原配方',method:'Hario Switch',dose:20,water:280,temp:90,clicks:26,seconds:180,drinkStyle:'hot',ice:0,source:'https://www.youtube.com/watch?v=gC8K40kZ_6E',desc:'先滴濾、後低溫浸泡。本站參考設定：前段 90°C，後段 70°C；數值與 C40 26 格均為可調整起點，未經原片逐項核實。',stages:[make('0:00',60,90,'開','0:30'),make('0:30',60,90,'開','1:15'),make('1:15',160,70,'關','1:45','先準備 70°C 水；關閥後注入。'),release('1:45')]},
    {id:'kasuya-new',title:'粕谷哲 · New Hybrid',author:'手法參考改編 · 非官方原配方',method:'Hario Switch',dose:20,water:300,temp:90,clicks:26,seconds:210,drinkStyle:'hot',ice:0,source:'https://www.youtube.com/watch?v=4FeUp_zNiiY',desc:'浸泡 → 滴濾 → 浸泡。本站參考設定：先關閥悶蒸，開閥分段注水，末段改用 75°C 水。數值與 C40 格數為可調整起點，非官方原版逐字食譜。',stages:[make('0:00',50,90,'關','0:40','關閥悶蒸。'),make('0:40',70,90,'開','1:30','開閥，注水至累積 120g。'),make('1:30',80,90,'開','2:10'),make('2:10',100,75,'關','2:45','先準備 75°C 水，關閥後注入。'),release('2:45')]},
    {id:'kasuya-iced-hybrid',title:'粕谷哲 · Hybrid 冰咖啡',author:'冰咖啡手法參考改編 · 非官方原配方',method:'Hario Switch',dose:20,water:200,temp:90,clicks:26,seconds:180,drinkStyle:'iced',ice:100,source:'https://philocoffea.com/blogs/kasuya/v0cxzmw1txg',desc:'參考混合萃取急冷思路嘅本站配方：20g 粉、熱沖水 200g、分享壺先放冰 100g；最後一段 70°C。唔係原片已核實配方，請按豆同融冰程度調整。',stages:[make('0:00',40,90,'開','0:30','分享壺先放 100g 冰；冰量不計入注水。'),make('0:30',40,90,'開','1:15'),make('1:15',120,70,'關','1:45'),release('1:45')]},
    {id:'kasuya-iced-46',title:'粕谷哲 · 4:6 急冷冰咖啡',author:'4:6 思路參考改編 · 非官方原配方',method:'Hario Switch',dose:20,water:200,temp:92,clicks:26,seconds:210,drinkStyle:'iced',ice:100,source:'https://philocoffea.com/blogs/kasuya/v0cxzmw1txg',desc:'本站急冷參考版：20g 粉、熱沖水 200g、冰 100g；五次各 40g 注水，全程開閥。前兩段佔熱沖水 40%；屬滴濾配方，並非 Switch 浸泡法，亦非原片已核實數值。',stages:[0,1,2,3,4].map(i=>make(clock(i*45),40,92,'開',i<4?clock((i+1)*45):null,i===0?'分享壺先放 100g 冰，全程開閥。':''))}
  ];
  additions.forEach(r=>{r.steps=r.stages.map(s=>`${s.start} ${s.action}${s.action==='注水'?` +${s.water}g / ${s.temp}°C`:''} · 閥門${s.valve}${s.until?` · 等至 ${s.until}`:' · 等流完'}`).join('\n');r.recipeTemplate=r.title+'（本站參考改編）';recipes.push(r);stageRecipes[r.id]=r.stages.map(s=>({...s}));const option=document.createElement('option');option.value=r.id;option.textContent=r.title+' · 參考版';$('#preset').append(option)});
  const extra=document.createElement('section');extra.className='drink-settings';extra.innerHTML='<div class="fields"><label>飲品形式<select name="drinkStyle"><option value="hot">熱咖啡</option><option value="iced">急冷冰咖啡</option></select></label><label>分享壺冰量 g<input name="ice" type="number" min="0" max="3000" step="0.1" value="0"></label></div><p class="hint">「總注水」只計沖過咖啡粉嘅水，唔包括冰。水＋冰係材料總量，唔等於成品重量。</p><p id="recipe-attribution" class="hint"></p><input type="hidden" name="recipeTemplate" value="">';
  form.elements.temp.closest('.fields').after(extra);
  const attribution=()=>{$('#recipe-attribution').textContent=form.elements.recipeTemplate.value?`食譜起點：${form.elements.recipeTemplate.value}；可以自行修改。`:''};
  const previousOpen=openBrew;openBrew=function(r){previousOpen(r);attribution()};
  const previousPreset=$('#preset').onchange;$('#preset').onchange=e=>{previousPreset(e);const r=recipes.find(x=>x.id===e.target.value);if(r){form.elements.drinkStyle.value=r.drinkStyle||'hot';form.elements.ice.value=r.ice||0;form.elements.recipeTemplate.value=r.recipeTemplate||r.title;attribution()}};
  const previousRender=renderStages;renderStages=function(){previousRender();stageSection.querySelectorAll('[data-index]').forEach(card=>{const i=Number(card.dataset.index);if(stages[i].action!=='注水')return;const label=document.createElement('label');label.innerHTML=`本段水溫 °C（選填）<input data-field="temp" type="number" min="1" max="100" step="0.1" placeholder="沿用上方水溫" value="${esc(stages[i].temp??'')}">`;card.querySelector('[data-target]').after(label)})};
  const previousCard=card;card=function(r){const html=previousCard(r);return r.drinkStyle==='iced'?html.replace('<h3>','<span class="badge">急冷 · 冰 '+esc(r.ice||0)+'g</span><h3>'):html};
  const note=document.createElement('p');note.className='recipe-reference-note';note.textContent='粕谷哲新增食譜標為「本站參考改編」，提供可用起點與原作者影片，並非已逐項核實嘅官方原配方。C40 格數為本站起點。';
  const previousPageRender=render;render=function(){previousPageRender();if(page==='recipes')$('#content').prepend(note.cloneNode(true))};
  const css=document.createElement('style');css.textContent='.drink-settings{margin:12px 0 18px;padding:15px;border:1px solid var(--line);border-radius:8px}.drink-settings label{margin-bottom:8px}.drink-settings p{margin:6px 0}.recipe-reference-note{padding:14px 18px;background:#f0e7d6;border-radius:8px;font-size:12px;line-height:1.9;margin-top:24px}';document.head.append(css);
  render();
})();
